    # Cancellation must run each trajectory's finally block, including
    # sandbox setup retries and DELETEs queued on the HTTP pool. Keep
    # polling those coroutines until the bounded grace period expires;
    # one three-second wait abandons healthy cleanup behind a slow setup.
    cleanup_deadline = time.monotonic() + _SHUTDOWN_TASK_GRACE_SEC
    while pending:
        remaining = cleanup_deadline - time.monotonic()
        if remaining <= 0:
            logger.warning(
                "[public-fully-async] Cleanup grace expired with %d generation tasks still cancelling",
                len(pending),
            )
            break
        done, pending = await asyncio.wait(
            pending, timeout=min(_PRODUCER_POLL_INTERVAL_SEC, remaining)
        )
        for task in done:
            try:
                task.result()
            except BaseException:
